import React, { useState } from 'react';
import styled from 'styled-components';
import SectionTitle from '../components/SectionTitle';
import ProjectCard from '../components/ProjectCard';
import Button from '../components/Button';

const ProjectsContainer = styled.section`
  padding: 5rem 0;

  @media (max-width: 768px) {
    padding: 3rem 0;
  }
`;

const Subtitle = styled.h3`
  font-size: 1.5rem;
  margin-bottom: 2rem;
  color: ${props => props.theme.fourthColor};

  @media (max-width: 768px) {
    font-size: 1.25rem;
  }
`;

const ProjectsGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  margin-top: 3rem;
  margin-bottom: 3rem;

  @media (max-width: 1024px) {
    grid-template-columns: repeat(2, 1fr);
  }

  @media (max-width: 576px) {
    grid-template-columns: 1fr;
  }
`;

const ButtonContainer = styled.div`
  display: flex;
  justify-content: center;
`;

const ProjectsPage = ({ strings }) => {
  const [showAll, setShowAll] = useState(false);

  const projects = [
    {
      id: 1,
      title: 'Logo Design',
      description: 'Corporate identity for a coffee shop',
      imageUrl: 'https://raw.githubusercontent.com/GlebPoroshin/DesignerWebApp/main/composeApp/src/commonMain/composeResources/drawable/figma_2.png'
    },
    {
      id: 2,
      title: 'UI/UX Design',
      description: 'Mobile app interface for fitness tracking',
      imageUrl: 'https://raw.githubusercontent.com/GlebPoroshin/DesignerWebApp/main/composeApp/src/commonMain/composeResources/drawable/figma_3.png'
    },
    {
      id: 3,
      title: 'Branding',
      description: 'Complete branding for a tech startup',
      imageUrl: 'https://raw.githubusercontent.com/GlebPoroshin/DesignerWebApp/main/composeApp/src/commonMain/composeResources/drawable/figma_4.png'
    },
    {
      id: 4,
      title: 'Print Design',
      description: 'Magazine layout and typography',
      imageUrl: 'https://raw.githubusercontent.com/GlebPoroshin/DesignerWebApp/main/composeApp/src/commonMain/composeResources/drawable/figma_5.png'
    },
    {
      id: 5,
      title: 'Web Design',
      description: 'E-commerce website redesign',
      imageUrl: 'https://raw.githubusercontent.com/GlebPoroshin/DesignerWebApp/main/composeApp/src/commonMain/composeResources/drawable/figma_6.png'
    },
    {
      id: 6,
      title: 'Illustration',
      description: 'Digital illustrations for a children\'s book',
      imageUrl: 'https://raw.githubusercontent.com/GlebPoroshin/DesignerWebApp/main/composeApp/src/commonMain/composeResources/drawable/figma_7.png'
    },
    {
      id: 7,
      title: '3D Modeling',
      description: 'Product visualization for marketing',
      imageUrl: 'https://raw.githubusercontent.com/GlebPoroshin/DesignerWebApp/main/composeApp/src/commonMain/composeResources/drawable/3d_2.png'
    },
    {
      id: 8,
      title: 'Packaging Design',
      description: 'Eco-friendly product packaging',
      imageUrl: 'https://raw.githubusercontent.com/GlebPoroshin/DesignerWebApp/main/composeApp/src/commonMain/composeResources/drawable/3d_3.png'
    },
    {
      id: 9,
      title: 'Advertisement',
      description: 'Social media marketing campaign',
      imageUrl: 'https://raw.githubusercontent.com/GlebPoroshin/DesignerWebApp/main/composeApp/src/commonMain/composeResources/drawable/adobe_5.png'
    }
  ];

  const displayedProjects = showAll ? projects : projects.slice(0, 3);

  return (
    <ProjectsContainer id="projects">
      <SectionTitle>{strings.projects}</SectionTitle>
      <Subtitle>{strings.myWorks}</Subtitle>

      <ProjectsGrid>
        {displayedProjects.map(project => (
          <ProjectCard key={project.id} project={project} />
        ))}
      </ProjectsGrid>

      <ButtonContainer>
        <Button onClick={() => setShowAll(!showAll)}>
          {showAll ? strings.hide : strings.view}
        </Button>
      </ButtonContainer>
    </ProjectsContainer>
  );
};

export default ProjectsPage;
